"""E25: rank the follow-up by band; findings covered at each depth, before and after."""
import json
from collections import Counter
from dataclasses import replace
from pathlib import Path

from unittest import mock

from analysis_service import questions as module
from analysis_service.frameworks import PACKAGES, Band
from analysis_service.questions import fact_questions
from analysis_service.report import Report

PATHS = sorted(Path("evals/baselines").glob("*/*.reports/*.report.json"))
DEPTHS = (3, 6, 10)


def covered(report, flat):
    flat_packages = {
        name: replace(package, rank=lambda claim: Band(0, ""))
        for name, package in PACKAGES.items()
    }
    catalog = report.assertions.catalog if report.assertions else None
    with mock.patch.object(module, "PACKAGES", flat_packages if flat else PACKAGES):
        questions = fact_questions(report.analyses, report.system_model, catalog)
    bands = {
        f"{b.framework}/{c.id}": PACKAGES[b.framework].rank(c).label
        for b in report.analyses for c in b.all_claims()
    }
    waits: dict[str, set] = {}
    for index, question in enumerate(questions):
        for finding in question.findings:
            waits.setdefault(finding, set()).add(index)
    out = {}
    for depth in DEPTHS:
        out[depth] = Counter(
            bands[f] for f, asked in waits.items() if max(asked) < depth
        )
        out[depth]["all"] = sum(1 for asked in waits.values() if max(asked) < depth)
    return out


table = {"before": {d: Counter() for d in DEPTHS}, "after": {d: Counter() for d in DEPTHS}}
for path in PATHS:
    report = Report.model_validate_json(path.read_text())
    for arm, flat in (("before", True), ("after", False)):
        for depth, counts in covered(report, flat).items():
            table[arm][depth].update(counts)
print(json.dumps({"reports": len(PATHS), **{a: {d: dict(c) for d, c in t.items()} for a, t in table.items()}}, indent=1))
